#include "stdafx.h"#include "ExerciseState.h"#define TIPFILE_DELIM	_T('*')extern HWND g_hWnd;CExerciseState::CExerciseState () : m_dwState (0), m_cTipsArr (1, TIPSARR_ST_COUNT){}CExerciseState::~CExerciseState (){}void CExerciseState::SetState (BYTE *pData, DWORD dwSize){	m_cCritSect.Lock ();	m_cTipsArr.RemoveAll ();	m_dwState = *((DWORD *)pData);	m_cCritSect.Unlock ();}void CExerciseState::SetUserTip (PACTIONTIPDATA pActTipData){	m_cCritSect.Lock ();	CString cTipInfo (pActTipData->szTipFile);	int nLen = cTipInfo.GetLength ();	int nPos = cTipInfo.Find (TIPFILE_DELIM);	if ( nPos > 0 && nPos < nLen - 1 )	{		CString cType = cTipInfo.Left (nPos);		CString cTipFile = cTipInfo.Right (nLen - nPos - 1);		DWORD dwType = (DWORD)_ttoi (cType);		if ( m_cTipsArr.Find ((PDWORD_PTR)&dwType, NULL, 0, pActTipData->szUser, (LPCTSTR)cTipFile, 0, 0, TRUE) < 0 )		{			DWORD_PTR dwValues[1] = { dwType };			LPCTSTR szValues[TIPSARR_ST_COUNT] = { pActTipData->szUser, (LPCTSTR)cTipFile };			m_cTipsArr.Add (dwValues, szValues);		}	}	m_cCritSect.Unlock ();}DWORD CExerciseState::GetUserState (LPCTSTR szUser){	m_cCritSect.Lock ();	DWORD dwState = m_dwState;	int nIndex = ((dwState & EXRCSTATE_STARTED) != 0) ? m_cTipsArr.FindString (szUser, TIPSARR_ST_USER, 0, TRUE) : -1;	if ( nIndex >= 0 )		dwState |= EXRCSTATE_TRAINMODE;	m_cCritSect.Unlock ();	return dwState;}void CExerciseState::RemoveTip (int nUniqueIdx){	m_cCritSect.Lock ();	int nIndex = m_cTipsArr.FindByUniqueIndex (nUniqueIdx);	if ( nIndex >= 0 )		m_cTipsArr.RemoveAt (nIndex);	m_cCritSect.Unlock ();}void CExerciseState::GetUserTip (LPCTSTR szUser, CString& cTip, BOOL bRemove){	m_cCritSect.Lock ();	cTip.Empty ();	int nIndex = m_cTipsArr.FindString (szUser, TIPSARR_ST_USER, 0, TRUE);	if ( nIndex >= 0 )	{		int nType = (int)m_cTipsArr.GetDWordAt (nIndex, 0);		CString cTipFile = m_cTipsArr.GetStringAt (nIndex, TIPSARR_ST_FILE);		if ( !cTipFile.IsEmpty () )		{			cTip.Format (_T("%d*%s"), nType, cTipFile);			if ( bRemove )			{				int nUniqueIdx = m_cTipsArr.GetUniqueIndex (nIndex);				if ( (nUniqueIdx >= 0) && g_hWnd && ::IsWindow (g_hWnd) )					::PostMessage (g_hWnd, WM_REMOVE_TIP, (WPARAM)nUniqueIdx, 0);			}		}	}	m_cCritSect.Unlock ();}